\set ON_ERROR_STOP on
SELECT public.report_test_assert(current_database()='moderation_test' OR current_setting('test.dm_disposable',true)='1','disposable resolve-conversation database');
RESET ROLE;
UPDATE auth.sessions SET created_at=clock_timestamp();
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
SELECT set_config('request.jwt.claims',jsonb_build_object('session_id','10000000-0000-0000-0000-000000000001','email','staff@example.test','aal','aal1','amr',jsonb_build_array(jsonb_build_object('method','otp','timestamp',extract(epoch FROM clock_timestamp()))))::text,false);
SET ROLE authenticated;
SELECT public.mc_call('start');
SELECT public.report_expect_error($q$SELECT public.mc_set_thread_resolved(current_setting('test.mc.thread')::uuid,true)$q$,'permission denied');
SELECT public.mc_call('resolve_thread',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000001','threadId',current_setting('test.mc.thread')));
SELECT public.mc_call('resolve_thread',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000001','threadId',current_setting('test.mc.thread')));
SELECT public.report_test_assert((SELECT count(*) FROM jsonb_array_elements(public.mc_call('conversations')->'items') t WHERE t->>'id'=current_setting('test.mc.thread'))=0,'resolved official threads leave the open list');
SELECT public.report_test_assert((public.mc_call('conversations','{"status":"resolved"}')->>'total')::int>=1,'resolved list includes the closed conversation');
SELECT public.report_test_assert((public.mc_call('conversation',jsonb_build_object('id',current_setting('test.mc.thread')))->'thread'->>'resolved_at') IS NOT NULL,'staff still open a resolved conversation');
SELECT public.report_expect_error(format('SELECT public.mc_call(''staff_reply'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''body'',''Staff cannot reply until this conversation is reopened.''))',current_setting('test.mc.thread')),'Reopen this conversation');
RESET ROLE;
SELECT public.report_test_assert((SELECT count(*) FROM public.mc_audit WHERE action='Conversation resolved' AND target=current_setting('test.mc.thread'))=1,'resolve retries write one audit row');
SELECT public.report_test_assert(NOT EXISTS(SELECT 1 FROM public.mc_audit WHERE action='Conversation resolved' AND (details ? 'body' OR details::text ILIKE '%still read%')),'resolve audit omits notification copy');
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
SET request.jwt.claims='{"session_id":"10000000-0000-0000-0000-000000000003","aal":"aal1"}';
SET ROLE authenticated;
SELECT public.report_test_assert((SELECT count(*) FROM jsonb_array_elements(public.mc_call('my_inbox')->'threads') t WHERE t->>'id'=current_setting('test.mc.thread') AND t->>'resolved_at' IS NOT NULL)=1,'recipient still sees a resolved conversation');
SELECT public.report_test_assert((public.mc_call('my_thread',jsonb_build_object('id',current_setting('test.mc.thread')))->>'resolvedAt') IS NOT NULL,'recipient can reread a resolved conversation');
SELECT public.report_expect_error(format('SELECT public.mc_call(''user_reply'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L,''body'',''I would like to keep this conversation going.''))',current_setting('test.mc.thread')),'resolved');
SELECT public.report_expect_error(format('SELECT public.mc_call(''resolve_thread'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L))',current_setting('test.mc.thread')),'Fresh staff verification');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000002';
SELECT set_config('request.jwt.claims',jsonb_build_object('session_id','10000000-0000-0000-0000-000000000002','email','staff@example.test','aal','aal1','amr',jsonb_build_array(jsonb_build_object('method','otp','timestamp',extract(epoch FROM clock_timestamp()))))::text,false);
SET ROLE authenticated;
SELECT public.mc_call('start');
SELECT public.report_expect_error(format('SELECT public.mc_call(''resolve_thread'',jsonb_build_object(''requestId'',gen_random_uuid(),''threadId'',%L))',current_setting('test.mc.direct')),'not found');
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000001';
SELECT set_config('request.jwt.claims',jsonb_build_object('session_id','10000000-0000-0000-0000-000000000001','email','staff@example.test','aal','aal1','amr',jsonb_build_array(jsonb_build_object('method','otp','timestamp',extract(epoch FROM clock_timestamp()))))::text,false);
SET ROLE authenticated;
SELECT public.mc_call('resolve_thread',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000002','threadId',current_setting('test.mc.direct')));
SELECT public.mc_call('reopen_thread',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000003','threadId',current_setting('test.mc.thread')));
SELECT public.mc_call('reopen_thread',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000003','threadId',current_setting('test.mc.thread')));
SELECT public.report_test_assert((public.mc_call('conversations')->>'total')::int>=1,'reopened official threads return to the open list');
SELECT public.mc_call('staff_reply',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000004','threadId',current_setting('test.mc.thread'),'body','Staff can reply again after reopening this conversation.'));
RESET ROLE;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000003';
SET request.jwt.claims='{"session_id":"10000000-0000-0000-0000-000000000003","aal":"aal1"}';
SET ROLE authenticated;
SELECT public.mc_call('user_reply',jsonb_build_object('requestId','90000000-0000-0000-0000-000000000005','threadId',current_setting('test.mc.thread'),'body','I can reply again after staff reopened this conversation.'));
RESET ROLE;
CREATE TEMP TABLE resolve_counts AS SELECT (SELECT count(*) FROM public.mc_threads WHERE resolved_at IS NOT NULL) r,(SELECT count(*) FROM public.mc_audit WHERE action IN ('Conversation resolved','Conversation reopened')) a;
\ir ../../../supabase/live-site/supabase-moderation-resolve-conversations.sql
SELECT public.report_test_assert((SELECT count(*) FROM public.mc_threads WHERE resolved_at IS NOT NULL)=(SELECT r FROM resolve_counts),'rerun preserves resolved conversations');
SELECT public.report_test_assert((SELECT count(*) FROM public.mc_audit WHERE action IN ('Conversation resolved','Conversation reopened'))=(SELECT a FROM resolve_counts),'rerun preserves resolve audit rows');
SELECT 'Live moderation resolve-conversation tests passed';
